K=json.load(open('known-forms.json'))
B={
"pallantis":" · also Pallās, -antis (m.) — Pallas, Evander's son (gen. sg., Pallantis nīvei)",
"insignibus":" · also insigne, -is (n.) — badge, trappings (abl. pl., as noun)",
"felicibus":" · also n. abl. pl. (fēlīcibus auspiciīs)",
"nivei":" · also m. gen. sg. (nīvei Pallantis)",
"qualem":" · also m. acc. sg. (quālem … flōrem)",
"segnes":" · also m. nom. pl. (haud sēgnēs)",
"ullis":" · also m./n. dat. pl. (caelestibus ūllīs)",
"mollis":" · also f. gen. sg. (mollis violae)",
}
N=json.load(open('novel-forms.json'))
miss=[n for n in N if n not in G]; extra=[g for g in G if g not in N]
assert not miss and not extra,(miss,extra)
out=dict(G); bro={}
for k,v in B.items():
    s=K[k]+v
    if len(s)<230: bro[k]=s
    else: print('too long',k,len(s))
out["__broaden__"]=bro
for k,v in G.items():
    if len(v)>=230: print('long',k,len(v))
json.dump(out,open('gloss.json','w'),ensure_ascii=False,indent=1)
print(len(G),list(bro))
